const assets = {"/index.html":{"body":"","contentType":"text/html; charset=utf-8"},"/products.html":{"body":"","contentType":"text/html; charset=utf-8"},"/product.html":{"body":"","contentType":"text/html; charset=utf-8"},"/style.css":{"body":"","contentType":"text/css; charset=utf-8"},"/script.js":{"body":"","contentType":"application/javascript; charset=utf-8"},"/images/hero.jpg":{"body":"","contentType":"image/jpeg"},"/images/about.jpg":{"body":"","contentType":"image/jpeg"},"/images/ppr.jpg":{"body":"","contentType":"image/jpeg"},"/images/pvc.jpg":{"body":"","contentType":"image/jpeg"},"/images/value.jpg":{"body":"","contentType":"image/jpeg"}};
const decodedAssets = new Map();

const readAsset = (pathname) => {
    const cached = decodedAssets.get(pathname);
    if (cached) {
        return cached;
    }

    const asset = assets[pathname];
    if (!asset) {
        return null;
    }

    const binary = atob(asset.body);
    const bytes = new Uint8Array(binary.length);

    for (let index = 0; index < binary.length; index += 1) {
        bytes[index] = binary.charCodeAt(index);
    }

    const decoded = { bytes, contentType: asset.contentType };
    decodedAssets.set(pathname, decoded);
    return decoded;
};

export default {
    async fetch(request) {
        const url = new URL(request.url);
        const pathname = url.pathname === "/"
            ? "/index.html"
            : url.pathname === "/products" || url.pathname === "/products/"
                ? "/products.html"
            : url.pathname.startsWith("/product/")
                ? "/product.html"
                : url.pathname;
        const asset = readAsset(pathname) || (!pathname.includes(".") ? readAsset("/index.html") : null);

        if (!asset) {
            return new Response("", { status: 404 });
        }

        const headers = new Headers({
            "Content-Type": asset.contentType
        });

        if (pathname.endsWith(".css") || pathname.endsWith(".js") || pathname.endsWith(".html")) {
            headers.set("Cache-Control", "no-cache, max-age=0, must-revalidate");
        } else if (!pathname.endsWith(".html")) {
            headers.set("Cache-Control", "public, max-age=31536000, immutable");
        }

        return new Response(asset.bytes, { headers });
    }
};
